@parity "wasm_builder/lib/src/serialize/serializer.dart:11 Serializable" abstract type Serializable end

"""
The binary writer: the bytes serialized so far, the source mappings they carry, and the traces
(a stack trace, or the serializer of a chunk written there) attached to byte positions for the watch
points, dart's Object narrowed to the two kinds it holds. dart's `_traces`
is a SplayTreeMap by position; a position is recorded only at `_index`, which only grows, so the
traces in recording order are sorted and dart's `lastKeyBefore` is a binary search over them.
"""
@parity "wasm_builder/lib/src/serialize/serializer.dart:17 Serializer" mutable struct Serializer
    # The prefix of `_data` up to `_index` holds the data serialized so far.
    _data::Vector{UInt8}
    _index::Int
    const _traces::Vector{Pair{Int,Union{Vector{Base.StackTraces.StackFrame},Serializer}}}
    source_map_serializer::SourceMapSerializer
    # dart's implicit constructor, the fields' initializers
    Serializer() = new(zeros(UInt8, 24), 0, Pair{Int,Union{Vector{Base.StackTraces.StackFrame},Serializer}}[], SourceMapSerializer())
end

"""
The interface of everything that serializes to wasm bytes: a method of `serialize(s, x)`.
"""
@parity "wasm_builder/lib/src/serialize/serializer.dart:12 Serializable.serialize" function serialize end

# dart's mutable static, set when a module with watch points serializes (module.dart:100)
@parity "wasm_builder/lib/src/serialize/serializer.dart:18 Serializer.traceEnabled" const Serializer_trace_enabled = Ref(false)

"""The current offset in the serialized data."""
@parity "wasm_builder/lib/src/serialize/serializer.dart:29 Serializer.offset" offset(s::Serializer)::Int = s._index

@parity "wasm_builder/lib/src/serialize/serializer.dart:33 Serializer._ensure" function _ensure(s::Serializer, size::Int)::Nothing
    # Ensure space for at least `size` additional bytes.
    if length(s._data) < s._index + size
        new_length = length(s._data) * 2
        while new_length < s._index + size
            new_length *= 2
        end
        resize!(s._data, new_length)
    end
    nothing
end

# dart's `_traces[_index] ??= data`: the first trace at a position is kept
@parity "wasm_builder/lib/src/serialize/serializer.dart:44 Serializer.debugTrace" function debug_trace(self::Serializer, data::Union{Vector{Base.StackTraces.StackFrame},Serializer})::Nothing
    (isempty(self._traces) || self._traces[end].first != self._index) && push!(self._traces, self._index => data)
    return nothing
end

# dart asserts `byte == byte & 0xFF` (serializer.dart:50); the argument's type makes any other
# byte unwritable.
@parity "wasm_builder/lib/src/serialize/serializer.dart:48 Serializer.writeByte" function write_byte(s::Serializer, byte::UInt8)::Nothing
    Serializer_trace_enabled[] && debug_trace(s, stacktrace())
    _ensure(s, 1)
    s._index += 1
    @inbounds s._data[s._index] = byte
    nothing
end

@parity "wasm_builder/lib/src/serialize/serializer.dart:55 Serializer.writeBytes" function write_bytes(s::Serializer, bytes::AbstractVector{UInt8})::Nothing
    Serializer_trace_enabled[] && debug_trace(s, stacktrace())
    n = length(bytes)
    _ensure(s, n)
    copyto!(s._data, s._index + 1, bytes, firstindex(bytes), n)
    s._index += n
    nothing
end

@parity "wasm_builder/lib/src/serialize/serializer.dart:61 Serializer.writeSigned" function write_signed(s::Serializer, value::Int)::Nothing
    # Julia's hex literals are unsigned (-0x40 is 0xc0), so dart's -0x40 and 0x40 read -64 and 64.
    while value < -64 || value >= 64
        write_byte(s, UInt8((value & 0x7F) | 0x80))
        value >>= 7
    end
    write_byte(s, UInt8(value & 0x7F))
end

@parity "wasm_builder/lib/src/serialize/serializer.dart:69 Serializer.writeUnsigned" function write_unsigned(s::Serializer, value::Int)::Nothing
    value >= 0 || reject!(Internal("wasm_builder/lib/src/serialize/serializer.dart:70 Serializer.writeUnsigned: negative value $value"), "write_unsigned")
    while value >= 0x80
        write_byte(s, UInt8((value & 0x7F) | 0x80))
        value >>= 7
    end
    write_byte(s, UInt8(value))
end

@parity "wasm_builder/lib/src/serialize/serializer.dart:78 Serializer.writeUnsignedByteCount" function Serializer_write_unsigned_byte_count(value::Int)::Int
    value >= 0 || reject!(Internal("wasm_builder/lib/src/serialize/serializer.dart:79 Serializer.writeUnsignedByteCount: negative value $value"), "write_unsigned_byte_count")
    count = 0
    while value >= 0x80
        count += 1
        value >>= 7
    end
    count + 1
end

# dart's static scratch buffer and its byte view, one array here: a ByteData and the Uint8List over its
# buffer share their storage, as one Vector{UInt8} does with itself
@parity "wasm_builder/lib/src/serialize/serializer.dart:89 Serializer._f32ByteData" const Serializer__f32_byte_data = zeros(UInt8, 4)

@parity "wasm_builder/lib/src/serialize/serializer.dart:90 Serializer._f32Uint8List" const Serializer__f32_uint8_list = Serializer__f32_byte_data

# dart writes a double through a Float32 view (serializer.dart:92); a Julia caller states the
# Float32 it means, so no rounding happens here. ByteData.setFloat32 little-endian: the value's bits,
# low byte first
@parity "wasm_builder/lib/src/serialize/serializer.dart:91 Serializer.writeF32" function write_f32(s::Serializer, value::Float32)::Nothing
    local bits = reinterpret(UInt32, value)
    for i in 0:3
        Serializer__f32_byte_data[i + 1] = (bits >> (8i)) % UInt8
    end
    write_bytes(s, Serializer__f32_uint8_list)
end

@parity "wasm_builder/lib/src/serialize/serializer.dart:96 Serializer._f64ByteData" const Serializer__f64_byte_data = zeros(UInt8, 8)

@parity "wasm_builder/lib/src/serialize/serializer.dart:97 Serializer._f64Uint8List" const Serializer__f64_uint8_list = Serializer__f64_byte_data

# ByteData.setFloat64 little-endian: the value's bits, low byte first
@parity "wasm_builder/lib/src/serialize/serializer.dart:98 Serializer.writeF64" function write_f64(s::Serializer, value::Float64)::Nothing
    local bits = reinterpret(UInt64, value)
    for i in 0:7
        Serializer__f64_byte_data[i + 1] = (bits >> (8i)) % UInt8
    end
    write_bytes(s, Serializer__f64_uint8_list)
end

@parity "wasm_builder/lib/src/serialize/serializer.dart:103 Serializer.writeName" function write_name(s::Serializer, name::String)::Nothing
    # A Julia String holds its UTF-8 encoding, which is what dart's utf8.encode produces.
    bytes = codeunits(name)
    write_unsigned(s, length(bytes))
    write_bytes(s, bytes)
end

# dart's Serializable is an interface: the classes that implement it beside their superclass (a defined
# function extends BaseFunction, an element segment is a kind of a sealed sum, the module is
# AbstractModule's one subtype) cannot also subtype it in Julia, so `write` names them beside it
@parity "wasm_builder/lib/src/serialize/serializer.dart:109 Serializer.write" function Base.write(s::Serializer, object::Union{Serializable,IR.ElementSegment,IR.DataSegment,IR.DefinedFunction,IR.ImportedFunction,IR.DefinedGlobal,IR.ImportedGlobal,IR.DefinedMemory,IR.ImportedMemory,IR.DefinedTag,IR.ImportedTag,IR.Module})::Nothing
    serialize(s, object)
    return nothing
end

@parity "wasm_builder/lib/src/serialize/serializer.dart:113 Serializer.writeList" function write_list(s::Serializer, objects::AbstractVector)::Nothing
    write_unsigned(s, length(objects))
    for object in objects
        write(s, object)
    end
    nothing
end

# a watch point inside the chunk prints its byte and the trace that wrote it, followed through the
# serializers each chunk was written by; a position with no trace at or before it is WasmTarget's own
# defect (dart's `lastKeyBefore(offset)!`)
@parity "wasm_builder/lib/src/serialize/serializer.dart:120 Serializer.writeData" function write_data(s::Serializer, chunk::Serializer, watch_points::Vector{Int}=Int[])::Nothing
    Serializer_trace_enabled[] && debug_trace(s, chunk)
    local chunk_data = data(chunk)
    for watch_point in watch_points
        if s._index <= watch_point < s._index + length(chunk_data)
            local byte_value = chunk_data[watch_point - s._index + 1]
            local trace::Union{Vector{Base.StackTraces.StackFrame},Serializer} = s
            local offset = watch_point
            while trace isa Serializer
                # dart's `containsKey(offset) ? offset : lastKeyBefore(offset)`: the last position at or before it
                local i = searchsortedlast(first.(trace._traces), offset)
                i == 0 && reject!(Internal("wasm_builder/lib/src/serialize/serializer.dart:120 Serializer.writeData: no trace at or before $offset for the watch point $watch_point"), "write_data")
                local key_offset = trace._traces[i].first
                trace = trace._traces[i].second
                offset -= key_offset
            end
            println("Watch $watch_point: 0x$(string(byte_value; base = 16, pad = 2))\n$trace")
        end
    end
    write_bytes(s, chunk_data)
end

@parity "wasm_builder/lib/src/serialize/serializer.dart:141 Serializer.data" data(s::Serializer)::Vector{UInt8} = s._data[1:s._index]
